<?php

namespace App\Console\Commands;

use App\Models\Language;
use App\Models\TranslationKey;
use App\Models\TranslationValue;
use Illuminate\Console\Command;
use Illuminate\Support\Arr;

class SeedDefaultTranslations extends Command
{
    protected $signature = 'translations:seed-default
        {--languages=fa,ar,tr,ckb : Comma separated locale codes to seed (en is always seeded)}
        {--namespaceMapOnly : Seed only keys, no values}
        {--fallback-to-en : Use English text when locale translation is missing}';

    protected $description = 'Seed base translation keys and values for UI (en + selected languages)';

    public function handle(): int
    {
        $langCodes = array_filter(array_map('trim', explode(',', (string) $this->option('languages'))));
        $langCodes = array_values(array_unique(array_merge(['en'], $langCodes)));

        $namespaceKeyValues = $this->defaultNamespaceMap();

        $seededKeys = 0;
        $seededValues = 0;

        foreach ($namespaceKeyValues as $namespace => $keyValuesByLocaleEn) {
            foreach ($keyValuesByLocaleEn as $key => $valuesByLocale) {
                // Idempotent upsert: every run updates existing keys and adds missing keys.
                $tkey = TranslationKey::query()->updateOrCreate(
                    [
                        'namespace' => $namespace,
                        'key' => $key,
                    ],
                    [
                        'description' => null,
                    ]
                );
                $seededKeys++;

                if ($this->option('namespaceMapOnly')) {
                    continue;
                }

                foreach ($langCodes as $locale) {
                    $lang = $this->resolveLanguageByCode($locale);

                    if (! $lang) {
                        continue;
                    }

                    $value = $this->resolveSeedValue($valuesByLocale, $locale);
                    if ($value === null) {
                        continue;
                    }

                    TranslationValue::query()->updateOrCreate(
                        [
                            'language_id' => $lang->id,
                            'translation_key_id' => $tkey->id,
                        ],
                        [
                            'value' => (string) $value,
                        ]
                    );
                    $seededValues++;
                }
            }
        }

        $this->info("Seeded keys: {$seededKeys}");
        if (! $this->option('namespaceMapOnly')) {
            $this->info("Seeded values: {$seededValues}");
        }

        return self::SUCCESS;
    }

    protected function resolveLanguageByCode(string $locale): ?Language
    {
        $locale = trim(mb_strtolower($locale));
        if ($locale === '') {
            return null;
        }

        // Support both Kurdish identifiers in DB: ckb (Sorani) and ku (legacy)
        $candidates = match ($locale) {
            'ckb' => ['ckb', 'ku'],
            'ku' => ['ku', 'ckb'],
            default => [$locale],
        };

        foreach ($candidates as $code) {
            $lang = Language::query()
                ->where('code', $code)
                ->where('is_active', true)
                ->first();
            if ($lang) {
                return $lang;
            }
        }

        return null;
    }

    protected function resolveSeedValue(array $valuesByLocale, string $locale): ?string
    {
        $locale = trim(mb_strtolower($locale));
        $english = isset($valuesByLocale['en']) ? trim((string) $valuesByLocale['en']) : '';
        $raw = $valuesByLocale[$locale] ?? null;

        // For Kurdish Sorani, allow map data written under "ku" as fallback source.
        if ($raw === null && $locale === 'ckb' && array_key_exists('ku', $valuesByLocale)) {
            $raw = $valuesByLocale['ku'];
        }

        if ($raw === null) {
            if ($this->option('fallback-to-en')) {
                return $english !== '' ? $english : null;
            }
            return null;
        }

        $value = trim((string) $raw);
        if ($value === '') {
            return null;
        }

        // Prevent seeding copied English text into non-English locales.
        if ($locale !== 'en' && $value === $english && ! $this->option('fallback-to-en')) {
            return null;
        }

        return $value;
    }

