                ],
                'privacy_intro' => [
                    'en' => 'RoniCRM ("we", "our", or "Roni Plus") operates the RoniCRM customer relationship management service. This Privacy Policy describes how we collect, use, and protect your information when you use our service. By using RoniCRM, you agree to this policy.',
                    'fa' => 'RoniCRM ("ما" یا "Roni Plus") سرویس مدیریت ارتباط با مشتری RoniCRM را ارائه می‌دهد. این سیاست حریم خصوصی توضیح می‌دهد چگونه اطلاعات شما را هنگام استفاده از سرویس جمع‌آوری، استفاده و محافظت می‌کنیم. با استفاده از RoniCRM، با این سیاست موافقید.',
                    'ar' => 'تدير RoniCRM ("نحن" أو "Roni Plus") خدمة إدارة علاقات العملاء RoniCRM. توضح سياسة الخصوصية هذه كيفية جمع معلوماتك واستخدامها وحمايتها عند استخدامك للخدمة. باستخدام RoniCRM، فإنك توافق على هذه السياسة.',
                    'tr' => 'RoniCRM ("biz" veya "Roni Plus"), RoniCRM müşteri ilişkileri yönetimi hizmetini işletir. Bu Gizlilik Politikası, hizmeti kullanırken bilgilerinizi nasıl topladığımızı, kullandığımızı ve koruduğumuzu açıklar. RoniCRM\'i kullanarak bu politikayı kabul etmiş olursunuz.',
                    'ku' => 'RoniCRM ("ئێمە" یان "Roni Plus") خزمەتی بەڕێوەبردنی پەیوەندی کڕیاری RoniCRM بەڕێوەدەبات. ئەم سیاسەتی نهێنییە ڕوون دەکاتەوە کە چۆن زانیارییەکانت کۆدەکەینەوە، بەکاردەهێنین و پاراستنیان دەکەین کاتێک خزمەتگوزارییەکە بەکاردەهێنیت. بە بەکارهێنانی RoniCRM، تۆ ڕازی دەبیت بە ئەم سیاسەتە.',
                ],
                'privacy_section_1_title' => [
                    'en' => '1. Information we collect',
                    'fa' => '1. اطلاعاتی که جمع‌آوری می‌کنیم',
                    'ar' => '1. المعلومات التي نجمعها',
                    'tr' => '1. Topladığımız bilgiler',
                    'ku' => '1. ئەو زانیارییانەی کۆیان دەکەینەوە',
                ],
                'privacy_section_1_body' => [
                    'en' => 'We may collect and store: (a) account information such as name, email address, and username; (b) customer and contact data you enter into RoniCRM (e.g. names, phone numbers, social handles); (c) usage data such as IP address, browser type, and actions within the service; and (d) session and authentication data necessary to operate the service securely.',
                    'fa' => 'ممکن است جمع‌آوری و ذخیره کنیم: (الف) اطلاعات حساب مانند نام، ایمیل و نام‌کاربری؛ (ب) داده‌های مشتری و مخاطب که در RoniCRM وارد می‌کنید (مثل نام، شماره تلفن و شناسه‌های شبکه اجتماعی)؛ (ج) داده‌های استفاده مانند IP، نوع مرورگر و فعالیت‌های داخل سرویس؛ و (د) داده‌های نشست و احراز هویت لازم برای اجرای امن سرویس.',
                    'ar' => 'قد نجمع ونخزن: (أ) معلومات الحساب مثل الاسم والبريد الإلكتروني واسم المستخدم؛ (ب) بيانات العملاء وجهات الاتصال التي تُدخلها في RoniCRM (مثل الأسماء وأرقام الهواتف ومعرفات التواصل الاجتماعي)؛ (ج) بيانات الاستخدام مثل عنوان IP ونوع المتصفح والإجراءات داخل الخدمة؛ و(د) بيانات الجلسة والمصادقة اللازمة لتشغيل الخدمة بأمان.',
                    'tr' => 'Şunları toplayıp saklayabiliriz: (a) ad, e-posta ve kullanıcı adı gibi hesap bilgileri; (b) RoniCRM\'e girdiğiniz müşteri ve kişi verileri (örn. adlar, telefon numaraları, sosyal medya hesapları); (c) IP adresi, tarayıcı türü ve hizmet içi işlemler gibi kullanım verileri; ve (d) hizmetin güvenli çalışması için gerekli oturum ve kimlik doğrulama verileri.',
                    'ku' => 'لەوانەیە ئەمانە کۆبکەینەوە و هەڵبگرین: (a) زانیارییەکانی هەژمار وەک ناو، ئیمەیڵ و ناوی بەکارهێنەر؛ (b) داتای کڕیار و پەیوەندی کە لە RoniCRM دەنووسیت (وەک ناو، ژمارەی تەلەفۆن، ناسنامەی تۆڕی کۆمەڵایەتی)؛ (c) داتای بەکارهێنان وەک IP، جۆری وێبگەڕ و کردارەکان لە خزمەتگوزارییەکە؛ و (d) داتای دانیشتن و ناساندن بۆ بەڕێوەبردنی پارێزراوی خزمەتگوزارییەکە.',
                ],
                'privacy_section_2_title' => [
                    'en' => '2. How we use your information',
                    'fa' => '2. چگونه از اطلاعات شما استفاده می‌کنیم',
                    'ar' => '2. كيف نستخدم معلوماتك',
                    'tr' => '2. Bilgilerinizi nasıl kullanırız',
                    'ku' => '2. چۆن زانیارییەکانت بەکاردەهێنین',
                ],
                'privacy_section_2_body' => [
                    'en' => 'We use the information we collect to provide, maintain, and improve RoniCRM; to communicate with you about the service (e.g. support, security notices); to comply with applicable law; and to protect the security and integrity of our systems. We do not sell your personal information to third parties. We may share data with service providers who assist in operating the service (e.g. hosting, email delivery), under strict confidentiality and data-processing terms.',
                    'fa' => 'از اطلاعات جمع‌آوری‌شده برای ارائه، نگهداری و بهبود RoniCRM استفاده می‌کنیم؛ برای ارتباط درباره سرویس (مانند پشتیبانی و اعلان‌های امنیتی)؛ رعایت قوانین؛ و حفاظت از امنیت و یکپارچگی سیستم‌ها. اطلاعات شخصی شما را به اشخاص ثالث نمی‌فروشیم. ممکن است داده‌ها را با ارائه‌دهندگان خدمات کمکی (مثل هاستینگ و ارسال ایمیل) با شرایط سخت‌گیرانه محرمانگی و پردازش داده به اشتراک بگذاریم.',
                    'ar' => 'نستخدم المعلومات التي نجمعها لتقديم RoniCRM وصيانته وتحسينه؛ وللتواصل معك بشأن الخدمة (مثل الدعم والتنبيهات الأمنية)؛ والامتثال للقانون؛ وحماية أمن وسلامة أنظمتنا. لا نبيع معلوماتك الشخصية لأطراف ثالثة. وقد نشارك البيانات مع مزودي خدمات يساعدون في تشغيل الخدمة (مثل الاستضافة وإرسال البريد) وفق شروط صارمة للسرية ومعالجة البيانات.',
                    'tr' => 'Topladığımız bilgileri RoniCRM\'i sunmak, sürdürmek ve geliştirmek; hizmetle ilgili sizinle iletişim kurmak (örn. destek, güvenlik bildirimleri); yasal yükümlülüklere uymak; ve sistemlerimizin güvenliğini ve bütünlüğünü korumak için kullanırız. Kişisel bilgilerinizi üçüncü taraflara satmayız. Verileri, hizmetin işletilmesine yardımcı olan sağlayıcılarla (örn. barındırma, e-posta gönderimi) sıkı gizlilik ve veri işleme şartları altında paylaşabiliriz.',
                    'ku' => 'زانیارییە کۆکراوەکان بەکاردەهێنین بۆ پێشکەشکردن، پاراستن و باشترکردنی RoniCRM؛ بۆ پەیوەندیکردن لەسەر خزمەتگوزارییەکە (وەک پاڵپشتی و ئاگادارکردنەوەی ئاسایش)؛ بۆ پابەندبوون بە یاسا؛ و بۆ پاراستنی ئاسایش و تەواوی سیستەمەکانمان. زانیاری تایبەتی تۆ بە لایەنی سێیەم ناکڕین. لەوانەیە داتا لەگەڵ پێشکەشکارانی خزمەتگوزاری هاوکاری (وەک هۆستینگ و ناردنی ئیمەیڵ) بەش بکەین، لە ژێر مەرجی توندی نهێنی و پرۆسێسکردنی داتا.',
                ],
                'privacy_section_3_title' => [
                    'en' => '3. Data security',
                    'fa' => '3. امنیت داده‌ها',
                    'ar' => '3. أمن البيانات',
                    'tr' => '3. Veri güvenliği',
                    'ku' => '3. ئاسایشی داتا',
                ],
                'privacy_section_3_body' => [
                    'en' => 'We implement technical and organizational measures to protect your personal data against unauthorized access, alteration, or disclosure. Access to data is restricted to authorized personnel. Passwords are stored using industry-standard hashing. We recommend you use a strong password and keep your login credentials confidential.',
                    'fa' => 'اقدامات فنی و سازمانی برای حفاظت از داده‌های شخصی شما در برابر دسترسی غیرمجاز، تغییر یا افشا اجرا می‌کنیم. دسترسی به داده‌ها محدود به افراد مجاز است. رمزها با هش استاندارد صنعت ذخیره می‌شوند. توصیه می‌کنیم رمز قوی انتخاب کرده و اطلاعات ورود را محرمانه نگه دارید.',
                    'ar' => 'نطبق إجراءات تقنية وتنظيمية لحماية بياناتك الشخصية من الوصول غير المصرح به أو التعديل أو الإفصاح. الوصول إلى البيانات مقصور على الموظفين المخولين. تُخزن كلمات المرور باستخدام تجزئة بمعايير الصناعة. نوصي باستخدام كلمة مرور قوية والحفاظ على سرية بيانات تسجيل الدخول.',
                    'tr' => 'Kişisel verilerinizi yetkisiz erişim, değişiklik veya ifşaya karşı korumak için teknik ve organizasyonel önlemler uygularız. Verilere erişim yalnızca yetkili personelle sınırlıdır. Şifreler sektör standardı hashing yöntemleriyle saklanır. Güçlü bir şifre kullanmanızı ve giriş bilgilerinizi gizli tutmanızı öneririz.',
                    'ku' => 'ئێمە ڕێکارە تەکنیکی و ڕێکخراوی جێبەجێ دەکەین بۆ پاراستنی داتای تایبەتی تۆ لە دەستڕاگەیشتنی بێ مۆڵەت، گۆڕانکاری یان ئاشکراکردن. دەستڕاگەیشتن بە داتا تەنها بۆ کەسانی مۆڵەتپێدراوە. تێپەڕەوشەکان بە هاشکردنی ستانداردی پیشەیی هەڵدەگیرێن. پێشنیار دەکەین تێپەڕەوشەی بەهێز بەکاربهێنیت و زانیاری چوونەژوورەوەت نهێنی بپارێزیت.',
                ],
                'privacy_section_4_title' => [
                    'en' => '4. Cookies and similar technologies',
                    'fa' => '4. کوکی‌ها و فناوری‌های مشابه',
                    'ar' => '4. ملفات تعريف الارتباط والتقنيات المشابهة',
                    'tr' => '4. Çerezler ve benzer teknolojiler',
                    'ku' => '4. کوکی و تەکنەلۆژیای هاوشێوە',
                ],
                'privacy_section_4_body' => [
                    'en' => 'We may use cookies and similar technologies to enable the site to function correctly, to keep you logged in, and to improve your experience. By continuing to use the site, you consent to such use. You can adjust your browser settings to limit or block cookies if you prefer.',
                    'fa' => 'ممکن است از کوکی‌ها و فناوری‌های مشابه برای عملکرد صحیح سایت، حفظ ورود شما و بهبود تجربه استفاده کنیم. با ادامه استفاده از سایت، با این استفاده موافقید. در صورت تمایل می‌توانید تنظیمات مرورگر را برای محدود یا مسدود کردن کوکی‌ها تغییر دهید.',
                    'ar' => 'قد نستخدم ملفات تعريف الارتباط وتقنيات مشابهة لتمكين الموقع من العمل بشكل صحيح، والحفاظ على تسجيل دخولك، وتحسين تجربتك. باستمرارك في استخدام الموقع، فإنك توافق على هذا الاستخدام. يمكنك تعديل إعدادات المتصفح لتقييد أو حظر ملفات تعريف الارتباط إذا رغبت.',
                    'tr' => 'Sitenin doğru çalışması, oturumunuzun açık kalması ve deneyiminizin iyileştirilmesi için çerezler ve benzer teknolojiler kullanabiliriz. Siteyi kullanmaya devam ederek bu kullanımı kabul etmiş olursunuz. İsterseniz tarayıcı ayarlarınızı değiştirerek çerezleri sınırlayabilir veya engelleyebilirsiniz.',
