                'terms_section_5_body' => [
                    'en' => 'RoniCRM is provided "as is". To the maximum extent permitted by law, we disclaim all warranties (express or implied) regarding availability, accuracy, or fitness for a particular purpose. We are not liable for any direct, indirect, incidental, or consequential damages arising from your use or inability to use the service.',
                    'fa' => 'RoniCRM به‌صورت "همان‌گونه که هست" ارائه می‌شود. تا حداکثر مجاز قانونی، هرگونه ضمانت صریح یا ضمنی درباره دسترس‌پذیری، دقت یا تناسب برای هدف خاص را رد می‌کنیم. در قبال خسارات مستقیم یا غیرمستقیم ناشی از استفاده یا عدم امکان استفاده از سرویس مسئولیتی نداریم.',
                    'ar' => 'يتم تقديم RoniCRM "كما هو". إلى أقصى حد يسمح به القانون، نخلي مسؤوليتنا عن جميع الضمانات (الصريحة أو الضمنية) المتعلقة بالتوفر أو الدقة أو الملاءمة لغرض معين. لا نتحمل مسؤولية أي أضرار مباشرة أو غير مباشرة أو عرضية أو تبعية ناتجة عن استخدامك للخدمة أو عدم قدرتك على استخدامها.',
                    'tr' => 'RoniCRM "olduğu gibi" sunulur. Yasanın izin verdiği azami ölçüde, kullanılabilirlik, doğruluk veya belirli bir amaca uygunlukla ilgili tüm açık/zımni garantileri reddederiz. Hizmeti kullanmanızdan veya kullanamamanızdan doğan doğrudan, dolaylı, arızi veya sonuçsal zararlardan sorumlu değiliz.',
                    'ku' => 'RoniCRM "وەک خۆی" پێشکەش دەکرێت. تا ڕادەی ڕێگەپێدراوی یاسا، هەموو گەرەنتییەکان (ڕاشکاوانە یان نادەربڕاو) لەبارەی بەردەستبوون، دروستی یان گونجاوی بۆ مەبەستێکی تایبەت ڕەت دەکەینەوە. ئێمە بەرپرسیار نین لە هیچ زیانێکی ڕاستەوخۆ یان ناراستەوخۆ کە لە بەکارهێنان یان نەبوونی توانا بۆ بەکارهێنانی خزمەتگوزارییەکەوە درووست ببێت.',
                ],
                'terms_section_6_title' => [
                    'en' => '6. Suspension and termination',
                    'fa' => '6. تعلیق و خاتمه',
                    'ar' => '6. التعليق والإنهاء',
                    'tr' => '6. Askıya alma ve fesih',
                    'ku' => '6. ڕاگرتن و کۆتاییهێنان',
                ],
                'terms_section_6_body' => [
                    'en' => 'We may suspend or terminate your access to RoniCRM if you breach these Terms or for technical or security reasons. Where reasonably possible, we will notify you via the site or email. Upon termination, your right to use the service ceases; we may retain or delete data in accordance with our Privacy Policy and applicable law.',
                    'fa' => 'اگر این شرایط را نقض کنید یا به دلایل فنی/امنیتی، ممکن است دسترسی شما به RoniCRM را تعلیق یا قطع کنیم. در صورت امکان منطقی از طریق سایت یا ایمیل اطلاع می‌دهیم. با پایان دسترسی، حق استفاده از سرویس متوقف می‌شود؛ و ممکن است داده‌ها را مطابق سیاست حریم خصوصی و قوانین نگه‌داری یا حذف کنیم.',
                    'ar' => 'قد نعلّق أو ننهي وصولك إلى RoniCRM إذا خالفت هذه الشروط أو لأسباب تقنية أو أمنية. حيثما أمكن بشكل معقول، سنبلغك عبر الموقع أو البريد الإلكتروني. عند الإنهاء، ينتهي حقك في استخدام الخدمة؛ وقد نحتفظ بالبيانات أو نحذفها وفقًا لسياسة الخصوصية والقانون المعمول به.',
                    'tr' => 'Bu Şartları ihlal etmeniz veya teknik/güvenlik nedenleriyle RoniCRM\'e erişiminizi askıya alabilir veya sonlandırabiliriz. Makul ölçüde mümkün olduğunda site veya e-posta ile sizi bilgilendiririz. Sonlandırma halinde hizmeti kullanma hakkınız sona erer; verileri Gizlilik Politikamız ve yürürlükteki yasalar doğrultusunda saklayabilir veya silebiliriz.',
                    'ku' => 'ئەگەر ئەم مەرجانەت پێشێل کرد یان بە هۆکاری تەکنیکی/ئاسایشی، لەوانەیە دەستڕاگەیشتنت بۆ RoniCRM ڕابگرین یان کۆتایی پێبهێنین. تا ئەوەی گونجاو بێت، لە ڕێگەی سایت یان ئیمەیڵ ئاگادارت دەکەینەوە. لە کاتی کۆتاییهاتن، مافی بەکارهێنانی خزمەتگوزارییەکە دەوەستێت؛ لەوانەیە داتا هەڵبگرین یان بسڕینەوە بەگوێرەی سیاسەتی نهێنی و یاسای جێبەجێ.',
