                'terms_section_7_body' => [
                    'en' => 'These Terms are governed by the laws applicable to Roni Plus. Any dispute shall first be addressed through good-faith negotiation; if unresolved, it may be submitted to the competent courts.',
                    'fa' => 'این شرایط تابع قوانین قابل اعمال بر Roni Plus است. هر اختلافی ابتدا از طریق مذاکره با حسن نیت پیگیری می‌شود؛ در صورت حل‌نشدن، می‌تواند به مراجع صالح ارجاع شود.',
                    'ar' => 'تخضع هذه الشروط للقوانين المعمول بها على Roni Plus. يجب معالجة أي نزاع أولًا عبر التفاوض بحسن نية؛ وإذا لم يُحل، يمكن إحالته إلى المحاكم المختصة.',
                    'tr' => 'Bu Şartlar, Roni Plus için geçerli yasalara tabidir. Her türlü uyuşmazlık öncelikle iyi niyetli müzakereyle ele alınır; çözülemezse yetkili mahkemelere taşınabilir.',
                    'ku' => 'ئەم مەرجانە بە یاساکانی جێبەجێ بۆ Roni Plus ڕێکدەخرێن. هەر ناکۆکییەک سەرەتا دەبێت بە دانوستانی باشە نیت چارەسەر بکرێت؛ ئەگەر چارەسەر نەبوو، دەتوانرێت بۆ دادگاکانی دەسەڵاتدار بنێردرێت.',
